{"new_text":"def policy_obs(p, prev_v, last):
    """Staged policy with hysteresis:
    - below 66 m: climb steadily (persist thermal est., correct drift)
    - 66-70 m loiter with a soft floor, so most in-band entries happen
      with vspeed already damped
    - inside band: hold zero vspeed; only if w est is small AND we are
      below 78 m with tiny drift do we push to the ceiling to bank ticks;
      bail above 80.5 m."""
    if p.tick == 0:
        w_est = 0.0
    else:
        w_est = ((p.v - prev_v) / 0.5) + 0.4 - BURN[last[0]](last[1]) + 0.1 * prev_v
    w_next = w_est

    if p.alt > 80.5:
        target_v = -0.6
    elif p.alt > BAND_HI:
        target_v = -0.1 if w_next > 0.15 else 0.3
    elif p.alt >= BAND_LO:
        target_v = 0.0
        if 76.0 <= p.alt <= 78.2 and abs(w_next) < 0.12 and abs(p.v) < 0.25:
            target_v = 0.35
    elif p.alt > 66.0:
        target_v = 0.35 if (p.alt + p.v > 68.8 and w_next > 0.1) else 0.7
    else:
        target_v = 0.8

    desired_accel = (target_v - p.v) / 0.5 + 0.1 * p.v - w_next
    burn_needed = desired_accel + 0.4
    lvl = round(burn_needed / 0.25)
    return ("up" if lvl >= 0 else "down", min(3, abs(lvl)))","old_text":"def policy_obs(p, prev_v, last):
